def transform(grid):
    h, w = len(grid), len(grid[0])

    # A uniform nonzero row or column separates the two panels.
    for r in range(h):
        if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r]):
            top, bottom = grid[:r], grid[r + 1:]
            n = min(len(top), len(bottom))
            return [
                [2 if top[i][j] != 0 and bottom[i][j] != 0 else 0
                 for j in range(min(len(top[i]), len(bottom[i])))]
                for i in range(n)
            ]

    for c in range(w):
        if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h)):
            left_width, right_start = c, c + 1
            right_width = w - right_start
            width = min(left_width, right_width)
            return [
                [2 if grid[r][j] != 0 and grid[r][right_start + j] != 0 else 0
                 for j in range(width)]
                for r in range(h)
            ]

    return grid
